  str_files_story_des_2307 = "Story 9",
  str_files_story_des_2310 = "Story 10",
  str_files_story_des_2501 = "It's just another day of getting numerous complaints about Charon. Time to have a talk with him.",
  str_files_story_des_2503 = "It's impossible to have a normal conversation with Charon. Try your best to get more information and you just might figure out his obsession.",
  str_files_story_des_2505 = "Story 5",
  str_files_story_des_2507 = "Story 7",
  str_files_story_des_2509 = "Story 9",
  str_files_story_des_2510 = "Story 10",
  str_files_story_des_2602 = "Story 2",
  str_files_story_des_2604 = "Story 4",
  str_files_story_des_2606 = "Story 6",
  str_files_story_des_2608 = "Story 8",
  str_files_story_des_2609 = "Story 9",
  str_files_story_des_2610 = "Story 10",
  str_files_story_des_2801 = "You keep feeling that something bad will happen... What is it? Ah, Is that Raphael over there? Why is she waving...like crazy?",
  str_files_story_des_2803 = "Raphael's pursuit to improve medical treatments is simply troublesome. Hopefully, she's not up to any shenanigans today, or even you will file a complaint...",
  str_files_story_des_2805 = "Story 5",
  str_files_story_des_2807 = "Story 7",
  str_files_story_des_2809 = "Story 9",
  str_files_story_des_2810 = "Story 10",
