  str_files_story_des_2908 = "Story 8",
  str_files_story_des_2909 = "Story 9",
  str_files_story_des_2910 = "Story 10",
  str_files_story_des_3202 = "Story 2",
  str_files_story_des_3204 = "Story 4",
  str_files_story_des_3206 = "Story 6",
  str_files_story_des_3301 = "Question: How well do you know this old friend you've hung out with every day? Do you know what she is truly thinking? Perhaps the answer is buried deep...",
  str_files_story_des_3303 = "Why does a survey with Vice feel more like a review? You're nervous and hope that Vice will go easy on you, regardless of what it is...",
  str_files_story_des_3305 = "Story 6",
  str_files_story_des_3307 = "Story 8",
  str_files_story_des_3310 = "Story 10",
  str_files_story_des_3501 = "Eho has been extremely unpunctual with his delivery recently. Why is that? Try talking to her about it...",
  str_files_story_des_3503 = "It turns out that Eho has a terrible sense of direction... It must be so hard for her to do her job... So, does copying maps really help her remember...?",
  str_files_story_des_3505 = "Story 5",
  str_files_story_des_3602 = "Story 1",
  str_files_story_des_3604 = "Story 3",
  str_files_story_des_3606 = "Story 5",
  str_files_story_des_3608 = "Story 7",
  str_files_story_des_3610 = "Story 10",
  str_files_story_des_3802 = "Ms. Gronru has been very concerned about the maintenance of the Colossus recently and seems to be highly interested and enthusiastic about it. The both of you are going to have the first official meeting today. Wonder what her personality is like?",
  str_files_story_des_3804 = "It seems that Ms. Gronru really enjoys games... I hope that this doesn't affect her daily work, otherwise it'll be hard to deal with...",
  str_files_story_des_3806 = "Story 6",
  str_files_story_des_3808 = "Story 8",
  str_files_story_des_3809 = "Story 9",
  str_files_story_des_3810 = "Story 10",
  str_files_story_des_4001 = "Story 1",
  str_files_story_des_4003 = "Story 3",
  str_files_story_des_4005 = "Story 5",
  str_files_story_des_4007 = "Story 7",
  str_files_story_des_4101 = "Ms. Blanc is always super busy for huge events. Why don't you check on her? It's even better if you can be of help, instead of getting in the way...",
  str_files_story_des_4103 = "Hmm... It seems like you really have made things worse. Ms. Blanc is now busier than before... Maybe you can make up for it somehow?",
  str_files_story_des_4105 = "Story 5",
  str_files_story_des_4107 = "Story 7",
  str_files_story_des_4402 = "Story 2",
  str_files_story_des_4404 = "Story 4",
  str_files_story_des_4406 = "Story 6",
  str_files_story_des_4408 = "Story 8",
  str_files_story_des_4601 = "Story 1",
  str_files_story_des_4603 = "Story 3",
  str_files_story_des_4605 = "Story 5",
  str_files_story_des_4701 = "Zoya has been acting suspiciously recently, erratic and elusive. Seems like... she is observing something?",
  str_files_story_des_4703 = "So, Zoya depends on Madam Hiiro in a special way. Wonder how that came about, and if she would actually share the story?",
  str_files_story_des_4705 = "Story 5",
  str_files_story_des_4801 = "As the person in charge of the Colossus, collecting information is also a job description, which seems to apply for the trip with Dayna.",
  str_files_story_des_4803 = "Sure enough, the work of a caravan isn't that easy... After trekking with Dayna for an unknown distance, you can hardly stand on your feet, let alone collect intel...",
  str_files_story_des_4805 = "Story 5",
  str_files_story_des_4807 = "Story 7",
  str_files_story_des_4902 = "Story 2",
  str_files_story_des_4904 = "Story 4",
